INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('URL_01', 'audit', 'url', 'Kalıcı bağlantı 3-5 kelime ve odak anahtar kelimeyi içeriyor', 'URL, Google\'ın sayfayı sınıflandırırken okuduğu ilk sinyaldir. Kısa ve anahtar kelimeli bir adres hem sıralamaya hem tıklanma oranına yardım eder; uzun adres arama sonucunda kırpılır.', 'Düzenleyicide sağ panelden \"Kalıcı Bağlantı\" alanını aç, WordPress\'in başlıktan ürettiği uzun adresi sil, 3-5 kelimeye indir.', 'critical', 3, 'rule', 10, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('URL_02', 'audit', 'url', 'Adres temiz: Türkçe karakter, büyük harf, alt çizgi ve tarih yok', 'Türkçe karakterler adreste yüzde işaretli kodlara dönüşür (ı → %C4%B1) ve bağlantıyı okunmaz yapar. Alt çizgi Google tarafından kelime ayırıcı sayılmaz, tire sayılır.', 'Yalnızca küçük harf, rakam ve tire kullan. Dönüşümü elle yap: ç→c, ğ→g, ı→i, ö→o, ş→s, ü→u.', 'critical', 3, 'rule', 20, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('URL_03', 'audit', 'url', 'Adreste gereksiz bağlaç veya dolgu kelime yok', '\"ve, ile, için, bir, bu\" gibi kelimeler adrese anlam katmaz, yalnızca uzatır.', 'Adresi yazdıktan sonra kelimeleri tek tek oku: çıkardığında anlam bozulmuyorsa çıkar.', 'medium', 1, 'rule', 30, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('URL_04', 'audit', 'url', 'Yayındaki bir yazının adresi değiştirilmedi; değiştiyse 301 yönlendirme kuruldu', 'Adres değişince eski sayfa 404 verir. O adrese verilmiş tüm bağlantılar ve birikmiş sıralama değeri bir anda yok olur.', 'Zorunlu değilse adrese dokunma. Değiştirmen gerekiyorsa Redirection eklentisinden eski adres → yeni adres için 301 kaydı aç.', 'critical', 3, 'manual', 40, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TTL_01', 'audit', 'title', 'SEO başlığı 50-60 karakter arasında', 'Google arama sonucundaki başlığı yaklaşık 580 piksel genişliğinde keser. Uzun başlık üç noktayla kırpılır ve mesajın can alıcı kısmı görünmez.', 'Yoast veya Rank Math kutusundaki \"SEO Başlığı\" alanını kullan; sayacı yeşil bandın içinde tut.', 'critical', 3, 'rule', 50, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TTL_02', 'audit', 'title', 'Odak anahtar kelime başlıkta, tercihen ilk 30 karakterde', 'Başlığın başındaki kelimelere hem Google hem de sonuçları göz gezdiren kullanıcı daha fazla ağırlık verir.', 'Başlık kalıbı: \"[Odak Kelime] + ayırt edici fayda\". Örnek: \"Kombi Basıncı Nasıl Ayarlanır? 4 Adımda Çözüm\".', 'critical', 3, 'rule', 60, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TTL_03', 'audit', 'title', 'SEO başlığı ile sayfadaki H1 birebir aynı değil', 'SEO başlığının işi arama sonucunda tıklatmak, H1\'in işi sayfaya giren okuyucuyu karşılamaktır. İki farklı iş, iki farklı metin ister.', 'H1\'i (yazı başlığını) daha doğal ve uzun yaz; SEO başlığını kısalt ve arama odaklı kur.', 'high', 2, 'rule', 70, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TTL_04', 'audit', 'title', 'Başlık site genelinde benzersiz, aynı başlığı taşıyan başka yazı yok', 'Aynı ya da çok benzer başlıklı iki yazı birbiriyle yarışır ve ikisi de sıralamada geriler. Buna anahtar kelime yamyamlığı denir.', 'Yayınlamadan önce Google\'da şöyle ara: site:siteadi.com \"başlık metni\". Sonuç çıkıyorsa başlığı farklılaştır.', 'high', 2, 'manual', 80, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TTL_05', 'audit', 'title', 'Başlıkta tamamı büyük harf veya çok sayıda ünlem/soru işareti yok', 'Google bu tür başlıkları güvenilmez bulup kendi yeniden yazar; senin yazdığın başlık hiç gösterilmez.', 'Yalnızca kelime başlarını büyük yaz. En fazla tek \"?\" ya da tek \"!\" kullan.', 'medium', 1, 'rule', 90, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TTL_06', 'audit', 'title', 'Marka adı kullanıldıysa yalnızca sonda ve ayırıcı ile', 'Başa konan marka adı, başlığın en değerli ilk karakterlerini harcar ve her yazıda aynı şeyi tekrarlar.', 'Kalıp: \"İçerik Başlığı | Marka\". Bu genelde temada otomatiktir, elle bir daha ekleme.', 'medium', 1, 'rule', 100, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TTL_07', 'audit', 'title', 'Başlıkta yıl geçiyorsa güncel yıl kullanılmış', 'Eski yıl içeren bir başlık kullanıcıya içeriğin bayat olduğunu söyler ve tıklanma oranını düşürür.', 'Yıl yazacaksan içeriği de gerçekten güncelle. Güncellemiyorsan yılı başlıktan çıkar.', 'medium', 1, 'rule', 110, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('MTA_01', 'audit', 'meta', 'Meta açıklama elle yazıldı (boş bırakılıp otomatik üretilmedi)', 'Boş bırakırsan Google sayfadan rastgele bir cümle çeker. Genelde menü metni ya da konuyla ilgisiz bir paragraf olur.', 'Yoast veya Rank Math kutusundaki \"Meta Açıklama\" alanını doldur. Şablon değişkeni değil, düz metin yaz.', 'critical', 3, 'rule', 120, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('MTA_02', 'audit', 'meta', 'Meta açıklama 120-158 karakter', '120 karakterin altında sana ayrılan alan boşa gider; 158 karakterin üstünde metin ortadan kesilir.', 'Sayacı takip et ve cümleyi 158\'de değil, anlamlı bir yerde bitir.', 'high', 2, 'rule', 130, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('MTA_03', 'audit', 'meta', 'Odak anahtar kelime meta açıklamada doğal biçimde geçiyor', 'Aranan kelime açıklamada kalın gösterilir. Göz gezdirilen sonuç sayfasında bu kalınlık dikkat çeker.', 'Kelimeyi cümlenin içine yedir; başa yapıştırmak yerine akıcı biçimde kullan.', 'high', 2, 'rule', 140, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('MTA_04', 'audit', 'meta', 'Meta açıklama net bir fayda vaadi veya eylem çağrısı içeriyor', 'Açıklama aslında bir reklam metnidir. Okuyucuya ne kazanacağını söylemezse alttaki sonuca tıklanır.', '\"Öğren, hesapla, adım adım, ücretsiz şablon\" gibi somut bir vaat ekle.', 'medium', 1, 'ai', 150, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('MTA_05', 'audit', 'meta', 'Meta açıklama, ilk paragrafın kopyala-yapıştırı değil', 'Aynı metnin hem sonuçta hem sayfada görünmesi tekrar hissi verir ve açıklamanın ikna gücünü harcar.', 'Açıklamayı içeriği yazdıktan sonra, bir özet olarak sıfırdan yaz.', 'medium', 1, 'ai', 160, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('MTA_06', 'audit', 'meta', 'Meta açıklama başka bir yazınınkiyle aynı değil', 'Tekrar eden açıklamalar Search Console\'da \"yinelenen meta açıklama\" uyarısı üretir.', 'Benzer konulu eski yazıyı aç ve açıklamasını bununla karşılaştır.', 'medium', 1, 'manual', 170, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('HDG_01', 'audit', 'heading', 'Sayfada tam olarak 1 adet H1 var', 'H1 sayfanın ana konusudur. Hiç yoksa konu belirsiz kalır, birden fazlaysa sinyal bölünür.', 'Yazı başlığı zaten H1\'dir. İçeriğe blok eklerken \"Başlık 1\"i asla seçme, H2\'den başla.', 'critical', 3, 'rule', 180, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('HDG_02', 'audit', 'heading', 'H1 yazının konusunu anlatıyor; site adı veya logo H1 değil', 'Her sayfada aynı H1 (site adı) varsa hiçbir sayfanın kendine ait bir konusu olmaz.', 'Bu genellikle tema hatasıdır. H1 site adıysa temayı düzelttir, yazı içinden çözmeye çalışma.', 'high', 2, 'rule', 190, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('HDG_03', 'audit', 'heading', 'Başlıklarda seviye atlanmamış (H2\'den sonra H4\'e geçilmemiş)', 'Başlık yapısı bir içindekiler ağacıdır. Seviye atlamak kırık bir içindekiler tablosu demektir; ekran okuyucu kullananlar da yolunu kaybeder.', 'Sıra şöyle: H2 → altında H3 → onun altında H4. Bir üst başlığa dönmek serbest, ileri atlamak değil.', 'critical', 3, 'rule', 200, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('HDG_04', 'audit', 'heading', 'Başlıklar yalnızca büyük veya kalın göstermek için kullanılmamış', 'Başlık bir anlam etiketidir, yazı tipi ayarı değil. Vurgu amaçlı açılan H3\'ler içeriğin yapısını bozar.', 'Metni öne çıkarmak istiyorsan kalın kullan. Başlığı yalnızca yeni bir bölüm başlatırken aç.', 'high', 2, 'ai', 210, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('HDG_05', 'audit', 'heading', 'En az 2 adet H2 var ve her H2 altında gerçek içerik var', 'Alt başlıksız uzun metin okunmaz. Google ayrıca öne çıkan snippet seçerken alt başlıkları kullanır.', 'Her 200-300 kelimede bir H2 aç ve altını boş bırakma.', 'high', 2, 'rule', 220, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('HDG_06', 'audit', 'heading', 'Alt başlıklar anlamlı; \"Giriş, Sonuç, Genel\" gibi boş başlıklar yok', 'Alt başlıklar uzun kuyruk aramalarını yakalar. \"Sonuç\" kelimesini kimse aramaz.', 'Alt başlığı kullanıcının soracağı soruya çevir: \"Sonuç\" yerine \"Hangi Yöntem Daha Ucuz?\".', 'medium', 1, 'ai', 230, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('HDG_07', 'audit', 'heading', 'Boş başlık yok, başlık içinde görsel veya bağlantı yok', 'Boş ya da görsel içeren başlık, içindekiler tablosunda boş satır olarak görünür.', 'Yazıyı bitirince başlık listesine hızlıca göz gezdir ve boş olanları sil.', 'medium', 1, 'rule', 240, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('CNT_01', 'audit', 'content', 'İçerik konuyu karşılayacak uzunlukta (en az 600 kelime)', 'Kelime sayısı tek başına bir sıralama faktörü değildir; ama konuyu eksik anlatan kısa içerik kullanıcının sorusunu cevaplamaz.', 'İlk üç rakibin başlıklarını aç, senin yazında olmayan alt konuları tespit edip ekle.', 'high', 2, 'rule', 250, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('CNT_02', 'audit', 'content', 'Odak anahtar kelime ilk 100 kelimede geçiyor', 'Girişin konuyu hemen netleştirmesi hem okuyucuyu sayfada tutar hem de konuyu erken bildirir.', 'İlk paragrafı \"Bu yazıda X\'in nasıl yapıldığını adım adım anlatıyoruz.\" kalıbıyla aç.', 'high', 2, 'rule', 260, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('CNT_03', 'audit', 'content', 'Anahtar kelime yoğunluğu %0,5 ile %2,5 arasında', 'Aynı kelimenin zorlama tekrarı hem okumayı bozar hem de spam sinyali üretir.', 'Eş anlamlı ve yakın kelimeler kullan. Kelimeyi zorla sıkıştırdığın cümleleri sil.', 'high', 2, 'rule', 270, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('CNT_04', 'audit', 'content', 'Paragraflar kısa; 150 kelimeyi aşan dev blok yok', 'Trafiğin büyük kısmı mobilden gelir. Telefonda 150 kelimelik bir blok tüm ekranı doldurur ve okuyucu bırakır.', 'Her paragrafı 2-4 cümlede kes. Fikir değişince yeni paragraf aç.', 'medium', 1, 'rule', 280, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('CNT_05', 'audit', 'content', 'İçerikte liste veya tablo var', 'Liste ve tablolar hem taranabilirliği artırır hem de öne çıkan snippet için en sık seçilen biçimdir.', 'Adımları numaralı liste, karşılaştırmaları tablo yap.', 'medium', 1, 'rule', 290, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('CNT_06', 'audit', 'content', 'Yazım ve dil bilgisi kontrolü yapıldı', 'İmla hatası güven kaybettirir ve Google\'ın E-E-A-T değerlendirmesinde doğrudan bir kalite sinyalidir.', 'Yayınlamadan önce metni baştan sona bir kez sesli oku.', 'high', 2, 'ai', 300, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('CNT_07', 'audit', 'content', 'İçerik özgün; başka siteden kopyalanmadı', 'Kopya içerik ya dizine eklenmez ya da değer görmez; ayrıca telif riski doğurur.', 'Alıntı yapacaksan tırnak içinde ver ve kaynağa bağlantı koy.', 'critical', 3, 'manual', 310, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('CNT_08', 'audit', 'content', 'Sayfanın üstünde ana soruyu doğrudan cevaplayan 40-60 kelimelik özet var', 'Hem öne çıkan snippet hem de yapay zekâ özetleri (AI Overviews, ChatGPT, Perplexity) bu tür net paragrafları alıntılar.', 'İlk H2\'nin hemen altına, soruyu tek paragrafta net cevaplayan bir bölüm koy.', 'high', 2, 'ai', 320, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('CNT_09', 'audit', 'content', 'Yazar adı ve güncelleme tarihi sayfada görünüyor', 'Kimin yazdığı ve ne zaman güncellendiği bilgisi bir E-E-A-T sinyalidir; özellikle sağlık ve finans konularında belirleyicidir.', 'Yazıyı doğru yazar hesabına ata ve temanın yazar kutusunu gösterip göstermediğini kontrol et.', 'medium', 1, 'rule', 330, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('IMG_01', 'audit', 'image', 'Öne çıkan görsel eklendi', 'Kategori listelerinde, sosyal medya paylaşımında ve Google Discover\'da kullanılan görsel budur. Yoksa yazı bomboş görünür.', 'Sağ panelden \"Öne Çıkan Görsel\" alanına en az 1200x630 piksel bir görsel seç.', 'high', 2, 'rule', 340, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('IMG_02', 'audit', 'image', 'Tüm görsellerde anlamlı alternatif metin var', 'Alternatif metin görme engelli kullanıcılar için zorunludur ve görsel aramasındaki neredeyse tek sıralama sinyalidir.', 'Görseli seç, \"Alternatif metin\" alanına görseli göremeyen birine anlatır gibi yaz.', 'critical', 3, 'rule', 350, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('IMG_03', 'audit', 'image', 'Alternatif metinler anahtar kelime yığması değil, görseli anlatıyor', 'Her görsele aynı anahtar kelimeyi yazmak spam sinyalidir ve görsel aramasında işe yaramaz.', '\"kombi basınç ayarı kombi basınç kombi\" değil; \"Kombi manometresinde 1,5 bar gösteren ibre\" yaz.', 'medium', 1, 'ai', 360, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('IMG_04', 'audit', 'image', 'Dosya adları açıklayıcı ve tireli (IMG_4821.jpg değil)', 'Dosya adı, görsel araması için ek bir bağlam sinyalidir.', 'Yüklemeden önce dosyayı yeniden adlandır: kombi-basinc-ayari.webp', 'medium', 1, 'rule', 370, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('IMG_05', 'audit', 'image', 'Görseller WebP veya AVIF biçiminde ve 200 KB altında', 'Görseller sayfa ağırlığının büyük kısmını oluşturur. Ağır görsel doğrudan LCP süresini ve sıralamayı bozar.', 'Yüklemeden önce TinyPNG veya Squoosh ile sıkıştır, WebP olarak dışa aktar.', 'high', 2, 'rule', 380, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('IMG_06', 'audit', 'image', 'Görsellerde genişlik ve yükseklik tanımlı', 'Boyut verilmezse sayfa yüklenirken içerik zıplar. Bu, Core Web Vitals\'taki CLS puanını düşürür.', 'WordPress bunu otomatik ekler; HTML bloğuyla elle görsel eklediysen sen yazmalısın.', 'medium', 1, 'rule', 390, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('IMG_07', 'audit', 'image', 'İlk ekrandaki görsel tembel yüklenmiyor, alttakiler yükleniyor', 'Üstteki görseli tembel yüklemek (lazy load) LCP süresini doğrudan geciktirir; alttakileri yüklememek ise boşuna veri indirir.', 'Öne çıkan görselde loading=\"lazy\" olmamalı. Eklentin \"ilk N görseli hariç tut\" ayarını destekliyorsa aç.', 'medium', 1, 'rule', 400, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('LNK_01', 'audit', 'link', 'En az 3 iç bağlantı var ve alakalı sayfalara gidiyor', 'İç bağlantılar hem otoriteyi site içinde dağıtır hem de yeni yazının keşfedilmesini hızlandırır.', 'Yazıyı bitirince konuyla ilgili üç eski yazı bul ve doğal geçtiği cümlede bağlantı ver.', 'high', 2, 'rule', 410, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('LNK_02', 'audit', 'link', 'Bağlantı metinleri açıklayıcı; \"buraya tıklayın\" değil', 'Bağlantı metni hedef sayfanın ne hakkında olduğunu anlatır. \"Tıklayın\" hiçbir şey anlatmaz.', 'Bağlantı verirken hedef sayfanın konusunu içeren 2-4 kelimeyi seçip bağla.', 'medium', 1, 'rule', 420, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('LNK_03', 'audit', 'link', 'Bu yeni yazıya en az 1 eski yazıdan bağlantı verildi', 'Hiçbir sayfadan bağlantı almayan yeni yazı sitede öksüz kalır ve çok geç keşfedilir.', 'İlgili eski yazıyı aç, uygun cümleye yeni yazının bağlantısını ekle ve güncelle.', 'high', 2, 'manual', 430, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('LNK_04', 'audit', 'link', 'Dış bağlantılar otoriter kaynaklara veriliyor', 'İddialı bilgileri kaynakla desteklemek doğrudan bir güvenilirlik sinyalidir.', 'Resmî kurum, üniversite veya sektör otoritesi sitelerini tercih et.', 'medium', 1, 'rule', 440, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('LNK_05', 'audit', 'link', 'Kırık bağlantı (404) yok', 'Kırık bağlantı hem kullanıcıyı çıkmaza sokar hem de sayfanın bakımsız olduğunu gösterir.', 'Yayından sonra denetimi çalıştır ve kırmızı çıkan bağlantıları düzelt.', 'critical', 3, 'rule', 450, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('LNK_06', 'audit', 'link', 'Sponsorlu veya ortaklık bağlantılarında rel=\"sponsored\" ya da \"nofollow\" var', 'Ücretli bağlantıları işaretlememek, Google\'ın bağlantı şeması yaptırımı kapsamına girer.', 'Bağlantı ekleme kutusunda \"nofollow\" veya \"sponsored\" seçeneğini işaretle.', 'high', 2, 'rule', 460, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TEC_01', 'audit', 'technical', 'Sayfa dizine eklenebilir (noindex yok)', 'noindex etiketi sayfayı Google\'dan tamamen siler. Tek satırlık bu hata tüm emeği boşa çıkarır.', 'Yoast veya Rank Math → Gelişmiş → \"Arama sonuçlarında görünsün mü?\" seçeneği Evet olmalı.', 'critical', 3, 'rule', 470, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TEC_02', 'audit', 'technical', 'Canonical etiketi sayfanın kendi adresini gösteriyor', 'Yanlış canonical, Google\'a \"asıl sayfa başkası\" der ve bu sayfayı sıralamadan çıkarır.', 'Yeni yazıyı kopyala-yapıştır ile açtıysan canonical eski yazıda kalmış olabilir; Gelişmiş sekmesinden kontrol et.', 'critical', 3, 'rule', 480, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TEC_03', 'audit', 'technical', 'Article veya BlogPosting şeması (JSON-LD) mevcut', 'Yapısal veri, arama sonucunda yazar ve tarih gibi zengin bilgilerin görünmesini sağlar.', 'SEO eklentisi bunu otomatik üretir; \"Şema\" sekmesinde türün Article olduğunu doğrula.', 'high', 2, 'rule', 490, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TEC_04', 'audit', 'technical', 'Open Graph başlık, açıklama ve görseli tanımlı', 'WhatsApp ve LinkedIn paylaşımlarında görünen önizleme kutusunu bu etiketler belirler. Yoksa bağlantı çıplak görünür.', 'Yoast veya Rank Math → Sosyal sekmesi. Görsel en az 1200x630 piksel olmalı.', 'high', 2, 'rule', 500, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TEC_05', 'audit', 'technical', 'Twitter/X kart etiketleri tanımlı', 'X paylaşımlarında büyük görselli kart çıkmasını sağlar ve tıklanmayı artırır.', 'twitter:card değeri \"summary_large_image\" olmalı.', 'medium', 1, 'rule', 510, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TEC_06', 'audit', 'technical', 'Sayfa mobil uyumlu (viewport etiketi var)', 'Google mobil öncelikli dizine ekleme yapar. Mobilde bozuk bir sayfa masaüstünde de değer kaybeder.', 'Bu tema kaynaklıdır. Eksikse temayı düzelttir.', 'high', 2, 'rule', 520, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TEC_07', 'audit', 'technical', 'Sayfa açılış hızı kontrol edildi (LCP 2,5 saniyenin altında)', 'Yavaş sayfa hem sıralamayı hem de dönüşümü düşürür.', 'PageSpeed Insights\'a adresi yapıştır ve mobil skoruna bak.', 'medium', 1, 'manual', 530, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TEC_08', 'audit', 'technical', 'Doğru kategori seçildi, etiket kalabalığı yapılmadı', 'Her yazıya on beş etiket açmak yüzlerce zayıf arşiv sayfası üretir ve dizini şişirir.', 'Tek kategori seç. En fazla 3-5 etiket kullan ve yenisini açmadan önce mevcutlara bak.', 'medium', 1, 'manual', 540, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('TEC_09', 'audit', 'technical', 'Yayın tarihi ve yazar doğru seçildi', 'Yanlış tarih içeriği bayat gösterir; yanlış yazar E-E-A-T sinyalini bozar.', 'Sağ panelden yayın tarihini ve Yazar alanını kontrol et.', 'medium', 1, 'manual', 550, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('PUB_01', 'audit', 'publish', 'Önizleme hem mobilde hem masaüstünde kontrol edildi', 'Taşan tablolar, kırılan görseller ve bozuk boşluklar yalnızca önizlemede ortaya çıkar.', 'Önizle bağlantısını yeni sekmede aç; ardından tarayıcı penceresini daraltıp mobil görünüme bak.', 'high', 2, 'manual', 560, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('PUB_02', 'audit', 'publish', 'Adres Search Console\'da dizine eklenmeye gönderildi', 'Manuel istek, yeni içeriğin taranmasını günlerden saatlere indirir.', 'Search Console → URL Denetimi → adresi yapıştır → \"Dizine eklenmeyi iste\".', 'medium', 1, 'manual', 570, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('PUB_03', 'audit', 'publish', 'Yazı yayınlanmadan önce baştan sona bir kez daha okundu', 'Denetim ölçebildiğini ölçer; anlatım bozukluğunu, yanlış bilgiyi ve eksik kalmış bir cümleyi yalnızca insan yakalar. Son okuma bu yüzden atlanamaz.', 'Yazıyı önizlemede aç ve okuyucu gibi baştan sona oku. Takıldığın her cümleyi düzelt.', 'critical', 3, 'manual', 580, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_P01', 'write', 'plan', 'Odak anahtar kelime belirlendi', 'Anahtar kelime seçilmeden yazılan içerik, hiç kimsenin aramadığı bir soruyu cevaplama riski taşır. Bütün kararlar bu kelimeye dayanır.', 'Tek bir odak kelime seç. Google\'da yazıp otomatik tamamlama ve alttaki \"İlgili aramalar\" bölümüne bak; insanların gerçekten nasıl aradığını oradan gör.', 'critical', 3, 'manual', 10, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_P02', 'write', 'plan', 'Arama niyeti tespit edildi', 'Google, kullanıcının ne beklediğine göre sıralar. Bilgi arayan birine ürün sayfası göstermez. Niyeti yanlış okursan içerik ne kadar iyi olursa olsun sıralanmaz.', 'Odak kelimeyi ara ve ilk 10 sonucun türüne bak: rehber mi, liste mi, ürün sayfası mı, video mu? Sen de aynı türü üret.', 'critical', 3, 'manual', 20, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_P03', 'write', 'plan', 'İlk 3 rakip içerik açıldı, alt konuları çıkarıldı', 'İlk sıradakiler Google\'ın \"bu konu böyle anlatılır\" onayını almış içeriklerdir. Neyi kapsadıklarını bilmeden eksik yazarsın.', 'İlk 3 sonucu aç, her birinin H2 başlıklarını bir kenara listele. Ortak başlıklar senin yazında da olmalı.', 'high', 2, 'manual', 30, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_P04', 'write', 'plan', 'Rakiplerin cevaplamadığı en az 1 soru bulundu', 'Aynı şeyi tekrar yazan bir içeriğin öne geçmesi için sebep yoktur. Ayırt edici tarafın olmalı.', 'Rakip listende eksik kalan soruyu, kendi deneyimini, güncel bir veriyi ya da somut bir örneği ekle.', 'high', 2, 'manual', 40, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_P05', 'write', 'plan', 'Sıkça sorulan sorular belirlendi', 'Okuyucunun aklına takılan sorular hem içeriğin alt başlıklarını verir hem de öne çıkan snippet ve yapay zekâ özetlerinde en çok alıntılanan bölümdür.', 'Odak kelimeyi Google\'da ara; sonuç sayfasındaki soru kutusundaki ve \"İlgili aramalar\" bölümündeki soruları topla. Bunlardan bir SSS bölümü çıkar.', 'medium', 1, 'manual', 50, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_P06', 'write', 'plan', 'Sitede aynı konuyu işleyen eski bir yazı olmadığı doğrulandı', 'Aynı konuda iki yazı birbiriyle yarışır ve ikisi de geriler. Buna anahtar kelime yamyamlığı denir.', 'Google\'da ara: site:siteadi.com \"odak kelime\". Benzer yazı çıkarsa yenisini yazmak yerine eskisini güncellemeyi düşün.', 'critical', 3, 'manual', 60, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_P07', 'write', 'plan', 'Hedef okuyucu ve bilgi seviyesi netleştirildi', 'Yeni başlayana yazılan metinle uzmana yazılan metin farklıdır. İkisinin arasında kalan yazı kimseye ulaşmaz.', 'Tek cümleyle yaz: \"Bu yazı, X konusunu hiç bilmeyen birine Y\'yi anlatıyor.\"', 'medium', 1, 'manual', 70, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_K02', 'write', 'outline', 'Önce H2 alt başlıkları yazıldı, iskelet çıkarıldı', 'İskeletsiz yazmak konunun dağılmasına ve aynı şeyin iki yerde anlatılmasına yol açar.', 'Metne başlamadan önce yalnızca alt başlıkları yaz. Sırasını beğenene kadar oynat, sonra doldurmaya başla.', 'high', 2, 'manual', 80, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_K03', 'write', 'outline', 'Alt başlıklar arama karşılığı olan ifadelerden seçildi', 'Alt başlıklar uzun kuyruk aramalarını yakalar ve öne çıkan snippet için kullanılır. \"Sonuç\" hiçbir arama karşılamaz.', 'Araştırma adımında topladığın soruları doğrudan alt başlığa çevir: \"Hangi Yöntem Daha Ucuz?\" gibi.', 'high', 2, 'manual', 90, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_K04', 'write', 'outline', 'Hedef uzunluk rakiplere bakılarak belirlendi', 'Uzunluk tek başına sıralamaz; ama rakipler konuyu 1500 kelimede anlatıyorsa 400 kelime eksik kalır.', 'Rakip yazıların uzunluğuna bak ve benzer bir hedef koy. Doldurmak için değil, kapsamak için yaz.', 'medium', 1, 'manual', 100, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_K05', 'write', 'outline', 'Hangi bölümün liste, hangisinin tablo olacağı kararlaştırıldı', 'Liste ve tablolar hem okumayı kolaylaştırır hem de öne çıkan snippet olarak en çok seçilen biçimdir.', 'İskelette işaretle: adımlar numaralı liste, karşılaştırmalar tablo, özellikler madde listesi.', 'medium', 1, 'manual', 110, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_Y01', 'write', 'writing', 'Giriş, okuyucunun sorusunu ilk iki cümlede karşılıyor', 'Okuyucu aradığı şeyi ilk ekranda göremezse geri döner. Uzun girişler en çok terk edilen bölümdür.', 'Girişte konuya ısınma yapma. İlk cümlede sorunu, ikinci cümlede yazının ne vaat ettiğini söyle.', 'critical', 3, 'manual', 120, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_Y02', 'write', 'writing', 'Ana sorunun 40-60 kelimelik net cevabı üste kondu', 'Hem öne çıkan snippet hem de yapay zekâ özetleri bu tür kısa, bağımsız paragrafları alıntılar.', 'İlk alt başlığın hemen altına, tek başına okunduğunda anlamlı olan kısa bir cevap paragrafı koy.', 'high', 2, 'manual', 130, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_Y03', 'write', 'writing', 'Odak anahtar kelime ilk 100 kelimede doğal biçimde geçiyor', 'Girişin konuyu erken netleştirmesi hem okuyucuyu tutar hem de konuyu bildirir.', 'Kelimeyi cümlenin içine yedir. Zorlama geldiyse cümleyi yeniden kur, kelimeyi sıkıştırma.', 'high', 2, 'manual', 140, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_Y04', 'write', 'writing', 'Her bölüm tek bir konuyu anlatıyor', 'Konu dağılan bölümler okuyucuyu yorar ve içindekiler yapısını anlamsızlaştırır.', 'Bölümü bitirince sor: bu başlığın altındaki her cümle bu başlıkla ilgili mi? Değilse taşı.', 'high', 2, 'manual', 150, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_Y05', 'write', 'writing', 'Paragraflar en az 2-4 cümle uzunluğunda', 'Tek cümlelik paragraflar metni parçalar; okuyucu fikri toparlayamaz ve yazı derinliksiz görünür. Bir paragraf, bir düşünceyi başından sonuna anlatacak kadar dolu olmalı.', 'Tek cümlede kalan paragrafı ya bir önceki paragrafla birleştir ya da düşünceyi açacak iki cümle daha ekle.', 'medium', 1, 'manual', 160, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_Y06', 'write', 'writing', 'Jargon açıklandı ya da sadeleştirildi', 'Anlamadığı terimle karşılaşan okuyucu geri döner. Terimi açıklamak otorite kaybı değil, kazancıdır.', 'Terimi ilk kullandığın yerde parantez içinde tek cümleyle açıkla.', 'medium', 1, 'manual', 170, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_Y07', 'write', 'writing', 'İddialar örnek, veri ya da kaynakla desteklendi', 'Desteklenmemiş iddia güven kaybettirir; kaynak göstermek doğrudan bir E-E-A-T sinyalidir.', 'Sayı verdiğin her yere kaynağını ekle. Genel geçer cümleleri somut örnekle değiştir.', 'high', 2, 'manual', 180, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_Y08', 'write', 'writing', 'Yazı baştan sona sesli okundu', 'Sesli okuma, gözle fark edilmeyen devrik ve uzun cümleleri anında ortaya çıkarır.', 'Nefesin yetmediği cümleyi böl, dilin dolandığı yeri yeniden yaz.', 'high', 2, 'manual', 190, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_Y09', 'write', 'writing', 'Yapay zekâ kullanıldıysa her bilgi tek tek doğrulandı', 'Dil modelleri kendinden emin biçimde yanlış bilgi, sahte istatistik ve olmayan kaynak üretebilir. Yayınlanan yanlış bilginin sorumlusu sensin.', 'Her sayıyı, tarihi, isim ve kaynağı bağımsız bir yerden doğrula. Doğrulayamadığını sil.', 'critical', 3, 'manual', 200, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_Y10', 'write', 'writing', 'Metin özgün; başka bir siteden kopyalanmadı', 'Kopya içerik ya dizine eklenmez ya da değer görmez; ayrıca telif riski doğurur.', 'Alıntıyı tırnak içinde ver ve kaynağa bağlantı koy. Gerisini kendi cümlelerinle yaz.', 'critical', 3, 'manual', 210, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_G01', 'write', 'assets', 'Öne çıkan görsel hazırlandı (en az 1200x630)', 'Kategori listelerinde, sosyal paylaşımlarda ve Discover\'da görünen görsel budur.', 'Yatay, üstünde metin varsa okunaklı bir görsel seç. 1200x630 en güvenli ölçüdür.', 'high', 2, 'manual', 220, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_G03', 'write', 'assets', 'Dosya adları açıklayıcı ve tireli yazıldı', 'Dosya adı görsel araması için ek bir bağlam sinyalidir; IMG_4821.jpg hiçbir şey anlatmaz.', 'Yüklemeden ÖNCE yeniden adlandır: kombi-basinc-ayari.webp', 'medium', 1, 'manual', 230, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_G08', 'write', 'assets', 'Görselin adına kendi marka adımız eklenmedi', 'Dosya adı, görselin ne olduğunu anlatmak içindir. Her görsele marka adını eklemek arama için bir katkı sağlamaz; adı uzatır, gerçek konuyu geriye iter ve tekrar eden kelime yığını izlenimi verir.', 'Görseli neyin resmi olduğuna göre adlandır: \"kombi-manometre-gostergesi.webp\". Marka adını yalnızca gerçekten markaya ait bir görselde kullan (logo, ürün fotoğrafı, ekip fotoğrafı gibi).', 'medium', 1, 'manual', 240, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_G04', 'write', 'assets', 'Her görsele alternatif metin yazıldı', 'Görme engelli kullanıcılar için zorunludur ve görsel aramasındaki neredeyse tek sıralama sinyalidir.', 'Görseli göremeyen birine anlatır gibi yaz. Anahtar kelimeyi tekrarlamak değil, görseli tarif etmek amaç.', 'critical', 3, 'manual', 250, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_G05', 'write', 'assets', 'En az 3 eski yazıya iç bağlantı verildi', 'İç bağlantılar otoriteyi site içinde dağıtır ve okuyucuyu sitede tutar.', 'Bağlantıyı hedef sayfanın konusunu içeren 2-4 kelimeye ver; \"buraya tıklayın\" yazma.', 'high', 2, 'manual', 260, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_G06', 'write', 'assets', 'En az 1 otoriter dış kaynağa bağlantı verildi', 'İddiaları kaynakla desteklemek güvenilirlik sinyalidir ve okuyucuya saygıdır.', 'Resmî kurum, üniversite ya da sektör otoritesi sitelerini tercih et.', 'medium', 1, 'manual', 270, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_G07', 'write', 'assets', 'Bu yazıya bağlantı verecek eski yazı belirlendi', 'Hiçbir sayfadan bağlantı almayan yeni yazı sitede öksüz kalır ve geç keşfedilir.', 'İlgili eski yazıyı şimdiden belirle. Yayınlar yayınlamaz o yazıya girip bağlantıyı ekle.', 'high', 2, 'manual', 280, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_H01', 'write', 'prepublish', 'SEO başlığı yazıldı, 50-60 karakter', 'Arama sonucunda görünen ve tıklanmayı belirleyen metin budur. Uzun olan kırpılır.', 'Kalıp: \"[Odak Kelime] + ayırt edici fayda\". Yazı başlığından farklı olabilir, arama odaklı kur.', 'critical', 3, 'manual', 290, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_H02', 'write', 'prepublish', 'Meta açıklama elle yazıldı, 120-158 karakter', 'Boş bırakırsan Google sayfadan rastgele bir cümle çeker; genelde işe yaramaz bir cümle olur.', 'İlk paragrafı kopyalama. Okuyucunun ne kazanacağını söyleyen yeni bir cümle yaz.', 'critical', 3, 'manual', 300, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_H03', 'write', 'prepublish', 'Kalıcı bağlantı kısaltıldı, Türkçe karakterler temizlendi', 'WordPress başlıktan uzun bir adres üretir; Türkçe karakterler adreste okunmaz kodlara dönüşür.', 'Yayınlamadan ÖNCE düzelt: 3-5 kelime, yalnızca küçük harf, rakam ve tire. Yayından sonra değiştirmek 301 gerektirir.', 'critical', 3, 'manual', 310, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_H04', 'write', 'prepublish', 'Kategori seçildi, etiket kullanılmadı', 'Her etiket kendi arşiv sayfasını üretir. Bu sayfalarda özgün içerik yoktur; dizini şişirir, birbirine benzeyen zayıf sayfalar yaratır ve kategori sayfalarıyla yarışır.', 'Tek ve doğru kategoriyi seç. Etiket alanını tamamen boş bırak; sınıflandırma için kategori yeterlidir.', 'medium', 1, 'manual', 320, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_H05', 'write', 'prepublish', 'Yazar ve yayın tarihi doğru seçildi', 'Kim yazdı ve ne zaman yazıldı bilgisi bir E-E-A-T sinyalidir.', 'Sağ panelden yazarı ve tarihi kontrol et; taslak uzun süre beklediyse tarih eskimiş olabilir.', 'medium', 1, 'manual', 330, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_H06', 'write', 'prepublish', 'Önizleme mobilde kontrol edildi', 'Taşan tablolar, kırılan görseller ve bozuk boşluklar yalnızca önizlemede ortaya çıkar.', 'Önizlemeyi yeni sekmede aç, sonra pencereyi daraltıp telefon genişliğinde bak.', 'high', 2, 'manual', 340, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
INSERT INTO checklist_items (code, `list`, category_key, label, why, how, severity, weight, mode, sort, is_active) VALUES ('WRT_H07', 'write', 'prepublish', 'Yayınlandı ve adres bu kayda girildi', 'Yazım listesi iyi bir taslak üretir ama yayınlanan sayfayı ölçmez. Ölçüm ancak adres girildikten sonra yapılabilir.', 'Yayınla, adresi yukarıdaki alana yapıştır ve \"Kontrol Et\"e bas. 47 madde otomatik denetlenecek.', 'high', 2, 'manual', 350, 1) ON DUPLICATE KEY UPDATE `list`=VALUES(`list`), category_key=VALUES(category_key), label=VALUES(label), why=VALUES(why), how=VALUES(how), severity=VALUES(severity), weight=VALUES(weight), mode=VALUES(mode), sort=VALUES(sort), is_active=1;
